glyph_50			equ ntc_font + 384		; "P"
glyph_5B			equ ntc_font + 472		; "["
glyph_5D			equ ntc_font + 488		; "]"
glyph_61			equ ntc_font + 520		; "a"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_66			equ ntc_font + 560		; "f"
glyph_67			equ ntc_font + 568		; "g"
glyph_69			equ ntc_font + 584		; "i"
glyph_6B			equ ntc_font + 600		; "k"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6E			equ ntc_font + 624		; "n"
glyph_6F			equ ntc_font + 632		; "o"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"
glyph_79			equ ntc_font + 712		; "y"
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack the caller's"
			DISPLAY "NTC memory: Reserved #A600-#BFFF (platform cpcmin)"
			DISPLAY "NTC memory: Reserved #C000-#FFFF (platform cpcmin)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
			IF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 42496)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #A600-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
			ASSERT ntc_bss + ntc_bss_size <= #10000, "out of memory: the arrays (after the last Option Memory Reserved / Paged range) do not fit below #10000"	; fwdref-ok
arr_arr		equ ntc_bss + 0		; 20 bytes
ntc_bss_size	equ 20
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 42496) || (ntc_bss >= 49152), "the program (or its arrays) reaches into the platform's reserved #A600-#BFFF (platform cpcmin: Option Memory Available frees it)"
			ASSERT (ntc_free <= 49152) || (ntc_bss >= 65536), "the program (or its arrays) reaches into the platform's reserved #C000-#FFFF (platform cpcmin: Option Memory Available frees it)"
			SAVEAMSDOS "LONGTEST.BIN", ntc_start, ntc_end - ntc_start, ntc_start
